    cmd.clone()
        .try_get_matches_from(["test", "--dog"])
        .unwrap_err();

    let matches = cmd
        .clone()
        .try_get_matches_from(["test", "--dog", "--mammal"])
        .unwrap();
    assert_eq!(matches.get_flag("dog"), true);
    assert_eq!(matches.get_flag("mammal"), true);
}

